<?php
require __DIR__.'/../includes/functions.php';require_login('admin');$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$year=(int)$_POST['academic_year_id'];$student=(int)$_POST['student_id'];db()->prepare('INSERT INTO student_enrollments(student_id,academic_year_id,grade,study_field,status) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE grade=VALUES(grade),study_field=VALUES(study_field),status=VALUES(status)')->execute([$student,$year,trim($_POST['grade']??''),trim($_POST['study_field']??''),$_POST['status']??'active']);audit('enrollment_saved','enrollment',$student);flash('ثبت‌نام سالانه ذخیره شد.');redirect('/admin/enrollments.php');}$years=db()->query('SELECT * FROM academic_years ORDER BY is_active DESC,title DESC')->fetchAll();$students=db()->query("SELECT id,name FROM users WHERE role='student' ORDER BY name")->fetchAll();$rows=db()->query('SELECT e.*,u.name student_name,y.title year_title FROM student_enrollments e JOIN users u ON u.id=e.student_id JOIN academic_years y ON y.id=e.academic_year_id ORDER BY y.is_active DESC,u.name')->fetchAll();layout_start('ثبت‌نام سالانه');?><div class="page-head"><div><p class="eyebrow">نسخه ۲.۵</p><h1>ثبت‌نام سالانه</h1></div><a class="button secondary" href="<?=e(url('/admin/index.php'))?>">بازگشت</a></div><div class="card"><h2>ثبت یا به‌روزرسانی ثبت‌نام</h2><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>سال تحصیلی<select name="academic_year_id" required><?php foreach($years as $y):?><option value="<?=$y['id']?>"><?=e($y['title'])?><?=$y['is_active']?' (فعال)':''?></option><?php endforeach;?></select></label><label>دانش‌آموز<select name="student_id" required><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><label>پایه<input name="grade"></label><label>رشته<input name="study_field"></label><label>وضعیت<select name="status"><option value="active">فعال</option><option value="archived">بایگانی</option></select></label><button class="button">ذخیره ثبت‌نام</button></form></div><div class="card table-wrap"><table><thead><tr><th>دانش‌آموز</th><th>سال</th><th>پایه</th><th>رشته</th><th>وضعیت</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['student_name'])?></td><td><?=e($r['year_title'])?></td><td><?=e($r['grade'])?></td><td><?=e($r['study_field'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php layout_end(); ?>
